import{_ as i,o as l,c as s,a2 as a}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 5 章 加载一个真正用得上的 Skill","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 5 章 加载一个真正用得上的 Skill.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 5 章 加载一个真正用得上的 Skill.md"}'),n={name:"bluebook/第一篇 使用手册：先把我用起来/第 5 章 加载一个真正用得上的 Skill.md"};function e(o,t,h,d,k,r){return l(),s("div",null,[...t[0]||(t[0]=[a(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 5 章 加载一个真正用得上的 Skill（易懂版）](../../easy/第5章 加载一个真正用得上的 Skill（易懂版）.md)</p></div><h1 id="第-5-章-加载一个真正用得上的-skill" tabindex="-1">第 5 章 加载一个真正用得上的 Skill <a class="header-anchor" href="#第-5-章-加载一个真正用得上的-skill" aria-label="Permalink to &quot;第 5 章 加载一个真正用得上的 Skill&quot;">​</a></h1><blockquote><p>本章目标：理解 Skill 的本质——把&quot;一次成功的做法&quot;封装成可随时调用的技能。学会加载、判断、评估 Skill，让重复劳动从此消失。</p></blockquote><h2 id="_5-1-什么是-skill" tabindex="-1">5.1 什么是 Skill <a class="header-anchor" href="#_5-1-什么是-skill" aria-label="Permalink to &quot;5.1 什么是 Skill&quot;">​</a></h2><p>Skill 是把&quot;一次成功的做法&quot;打包成<strong>可随时调用的技能</strong>。它类似电脑里的快捷方式：不用每次重讲方法，喊名字就能用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill = 明确的使用方法 + 执行步骤 + 输入输出约定</span></span></code></pre></div><h3 id="_5-1-1-生活中的类比" tabindex="-1">5.1.1 生活中的类比 <a class="header-anchor" href="#_5-1-1-生活中的类比" aria-label="Permalink to &quot;5.1.1 生活中的类比&quot;">​</a></h3><p>想想新员工入职：公司不会让新人每次报销都重新研究流程，而是给一本《报销 SOP》——照着做就行。<strong>Skill 就是我的 SOP 手册。</strong></p><h3 id="_5-1-2-skill-解决的问题" tabindex="-1">5.1.2 Skill 解决的问题 <a class="header-anchor" href="#_5-1-2-skill-解决的问题" aria-label="Permalink to &quot;5.1.2 Skill 解决的问题&quot;">​</a></h3><p><strong>同一件事，每次都按最佳实践做，而不是每次从头想。</strong></p><ul><li>没有 Skill：每次写报告都重新纠结结构；</li><li>有 Skill：一句话调用，格式、结构、规范全部就位。</li></ul><h2 id="_5-2-我身上的-skill-长什么样" tabindex="-1">5.2 我身上的 Skill 长什么样 <a class="header-anchor" href="#_5-2-我身上的-skill-长什么样" aria-label="Permalink to &quot;5.2 我身上的 Skill 长什么样&quot;">​</a></h2><p>我身上就挂着一些 Skill，比如提交代码（commit）、评审 PR（review-pr）、处理 PDF（pdf）等。一个 Skill 通常包含四个部分：</p><table tabindex="0"><thead><tr><th>部分</th><th>内容</th><th>示例（commit）</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>调用名</td><td><code>commit</code></td></tr><tr><td><strong>说明</strong></td><td>什么时候用</td><td>&quot;提交代码前，先看 diff 再提交&quot;</td></tr><tr><td><strong>步骤</strong></td><td>执行流程</td><td>查状态 → 看改动 → 写规范 commit message → 提交</td></tr><tr><td><strong>约定</strong></td><td>约束与边界</td><td>不强制 push、不用 --no-verify</td></tr></tbody></table><h3 id="_5-2-1-标准-skill-的结构示例" tabindex="-1">5.2.1 标准 Skill 的结构示例 <a class="header-anchor" href="#_5-2-1-标准-skill-的结构示例" aria-label="Permalink to &quot;5.2.1 标准 Skill 的结构示例&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># commit 技能</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 用途</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">提交代码时使用，确保每次提交规范、可回溯。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 触发条件</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">用户要求&quot;提交代码&quot;、&quot;commit&quot;时。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 执行步骤</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> git status 查看改动文件</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 逐个文件过 diff，理解改动内容</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 写规范的 commit message（类型 + 摘要 + 说明）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 提交（不 push，除非用户明确要求）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 边界</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不强制 push</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不使用 --no-verify</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不 amend 历史提交（除非用户要求）</span></span></code></pre></div><h2 id="_5-3-怎么加载一个-skill" tabindex="-1">5.3 怎么加载一个 Skill <a class="header-anchor" href="#_5-3-怎么加载一个-skill" aria-label="Permalink to &quot;5.3 怎么加载一个 Skill&quot;">​</a></h2><p>两步走：</p><h3 id="_5-3-1-第一步-报技能名-目标" tabindex="-1">5.3.1 第一步：报技能名 + 目标 <a class="header-anchor" href="#_5-3-1-第一步-报技能名-目标" aria-label="Permalink to &quot;5.3.1 第一步：报技能名 + 目标&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：用 commit 技能，帮我提交这次的改动</span></span>
<span class="line"><span>我：（加载 commit Skill）先 git status 看改动 → 逐个文件过 diff → 写规范的提交信息 → 提交</span></span></code></pre></div><h3 id="_5-3-2-第二步-想不起名字就描述目标" tabindex="-1">5.3.2 第二步：想不起名字就描述目标 <a class="header-anchor" href="#_5-3-2-第二步-想不起名字就描述目标" aria-label="Permalink to &quot;5.3.2 第二步：想不起名字就描述目标&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：帮我提交代码  ← 没提技能名</span></span>
<span class="line"><span>我：（自动匹配 commit Skill）好的，按提交规范来。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">记忆技巧</p><p><strong>技能名想不起来完全没关系，描述目标即可，我会自动匹配。</strong> 想知道有什么技能，直接问&quot;你有哪些技能&quot;。</p></div><h2 id="_5-4-skill-的正确使用场景" tabindex="-1">5.4 Skill 的正确使用场景 <a class="header-anchor" href="#_5-4-skill-的正确使用场景" aria-label="Permalink to &quot;5.4 Skill 的正确使用场景&quot;">​</a></h2><h3 id="_5-4-1-该用-skill-的判断标准" tabindex="-1">5.4.1 该用 Skill 的判断标准 <a class="header-anchor" href="#_5-4-1-该用-skill-的判断标准" aria-label="Permalink to &quot;5.4.1 该用 Skill 的判断标准&quot;">​</a></h3><p><strong>这件事你（或团队）会反复做吗？</strong></p><table tabindex="0"><thead><tr><th>判断</th><th>结论</th></tr></thead><tbody><tr><td>会，且每次做法一致</td><td>✅ 值得做成/调用 Skill</td></tr><tr><td>会，但每次差异大</td><td>⚠️ 做成 Skill 时保留参数化空间</td></tr><tr><td>一次性、不重复</td><td>❌ 直接对话即可</td></tr></tbody></table><h3 id="_5-4-2-什么时候别用-skill" tabindex="-1">5.4.2 什么时候别用 Skill <a class="header-anchor" href="#_5-4-2-什么时候别用-skill" aria-label="Permalink to &quot;5.4.2 什么时候别用 Skill&quot;">​</a></h3><ul><li><strong>一次性、不重复的任务</strong>：直接对话即可，加载 Skill 反而绕；</li><li><strong>需要即兴发挥的任务</strong>：Skill 反而束缚（如&quot;帮我头脑风暴 10 个点子&quot;）；</li><li><strong>超出技能边界的任务</strong>：Skill 会明确告诉我做不了——这也是好事，边界清晰。</li></ul><div class="warning custom-block"><p class="custom-block-title">重要认知</p><p><strong>Skill 是锦上添花，不是银弹。</strong> 它是&quot;经验封装&quot;，不是&quot;能力上限&quot;。判断标准只有一个：这件事你会反复做吗？</p></div><h2 id="_5-5-评估一个-skill-好不好" tabindex="-1">5.5 评估一个 Skill 好不好 <a class="header-anchor" href="#_5-5-评估一个-skill-好不好" aria-label="Permalink to &quot;5.5 评估一个 Skill 好不好&quot;">​</a></h2><p>用三个问题评估：</p><table tabindex="0"><thead><tr><th>问题</th><th>好 Skill</th><th>差 Skill</th></tr></thead><tbody><tr><td>触发条件清楚吗？</td><td>知道何时该用</td><td>含糊，靠猜</td></tr><tr><td>步骤可执行吗？</td><td>每步都是动作</td><td>抽象、跳过关键细节</td></tr><tr><td>边界明确吗？</td><td>知道什么不做</td><td>无限扩张、越权</td></tr></tbody></table><p><strong>评估结论反过来就是设计原则</strong>——第 17 章&quot;打造 Skill&quot;会带你亲手做一个。</p><h2 id="_5-6-本章练习" tabindex="-1">5.6 本章练习 <a class="header-anchor" href="#_5-6-本章练习" aria-label="Permalink to &quot;5.6 本章练习&quot;">​</a></h2><ol><li>让我列出当前可用的全部 Skill，并逐个说明用途。</li><li>挑一个与你的工作相关的 Skill，实际调用一次。</li><li>记录：这个 Skill 解决了我什么问题？省了多少时间？</li><li>用 5.5 节的三个问题，评估你刚调用的 Skill 好不好，并把结论告诉我。</li></ol><hr><blockquote><p>小结：Skill 的本质是<strong>经验的封装</strong>——用别人的 Skill 是抄作业，做自己的 Skill 是写教材。<strong>加载 Skill 是本章的内容，打造 Skill 在第 17 章。</strong> 下一章，我们让 AI 记住你——记忆系统。</p></blockquote>`,38)])])}const g=i(n,[["render",e]]);export{c as __pageData,g as default};
